def priority(item: float, bins: np.ndarray) -> np.ndarray:
    current_load = bins - (bins - item).clip(min=0)
    avg_load = np.mean(current_load)
    load_deviation = avg_load - current_load
    # Prioritize bins with lower load compared to average
    return np.clip(load_deviation, 0, None)
